from dataclasses import dataclass
from typing import Generic, TypeVar

T = TypeVar("T")

class Option(Generic[T]):
    pass

@dataclass(frozen=True)
class Some(Option[T]):
    value: T

class NoneOption(Option[None]):
    _instance = None
    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(NoneOption, cls).__new__(cls)
        return cls._instance
    def __repr__(self):
        return "NoneOption"

NONE = NoneOption()

def divide(a: float, b: float) -> Option[float]:
    if b == 0:
        return NONE
    return Some(a / b)

def print_result(opt: Option[float]) -> None:
    if isinstance(opt, Some):
        print(f"Result: {opt.value}")
    else:
        print("Error: Division by zero")

if __name__ == "__main__":
    res1 = divide(10, 2)
    res2 = divide(10, 0)
    print_result(res1)
    print_result(res2)

