module benchmark/solution

import std/io (println)
import std/net (httpRequest)
import std/json (encode, jo, ja, kv, js, jnum, Json)

-- Algebraic Data Type for user status
type Status = Active | Inactive(string)

-- Record type for user data
type User = { id: int, name: string, score: int, status: Status }

-- Pure helper function to check if a user is active
export func isUserActive(user: User) -> bool {
  match user.status {
    Active => true,
    Inactive(_) => false
  }
}

-- Higher-order function: filter (from prompt)
export func filter[a](pred: func(a) -> bool, xs: [a]) -> [a] {
  match xs {
    [] => [],
    Cons(x, rest) =>
      if pred(x)
      then Cons(x, filter(pred, rest))
      else filter(pred, rest)
  }
}

-- Higher-order function: map (from prompt)
export func map[a, b](f: func(a) -> b, xs: [a]) -> [b] {
  match xs {
    [] => [],
    Cons(x, rest) => Cons(f(x), map(f, rest))
  }
}

-- Pure function to convert a User record to a JSON value
export func userToJson(user: User) -> Json {
  jo([
    kv("id", jnum(intToFloat(user.id))),
    kv("name", js(user.name)),
    kv("score", jnum(intToFloat(user.score)))
  ])
}

-- Unit test for the isUserActive function
test "isUserActive correctly identifies status" =
  let activeUser = {id: 1, name: "A", score: 0, status: Active} in
  let inactiveUser = {id: 2, name: "B", score: 0, status: Inactive("test")} in
  isUserActive(activeUser) == true && isUserActive(inactiveUser) == false

-- Recursive function for property testing
export func reverse[a](xs: [a]) -> [a] {
  letrec rev_acc = \acc, list.
    match list {
      [] => acc,
      Cons(h, t) => rev_acc(Cons(h, acc), t)
    }
  in rev_acc([], xs)
}

-- Property test for the reverse function
property "reverse twice is identity" (xs: List[int]) =
  reverse(reverse(xs)) == xs

-- Main entry point of the program
export func main() -> () ! {IO, Net} {
  let users = [
    {id: 1, name: "Alice", score: 100, status: Active},
    {id: 2, name: "Bob", score: 50, status: Inactive("vacation")},
    {id: 3, name: "Charlie", score: 120, status: Active}
  ];

  -- 1. Filter for active users using our higher-order function
  let activeUsers = filter(isUserActive, users);

  -- 2. Convert the filtered users to JSON values
  let activeUsersJson = map(userToJson, activeUsers);

  -- 3. Build the final JSON body payload
  let jsonPayload = jo([
    kv("report_name", js("Active Users Report")),
    kv("user_count", jnum(intToFloat(length(activeUsers)))),
    kv("users", ja(activeUsersJson))
  ]);
  let jsonBody = encode(jsonPayload);

  -- 4. Define custom HTTP headers
  let headers = [
    {name: "Content-Type", value: "application/json"},
    {name: "X-AILANG-Version", value: "0.3.22"}
  ];

  -- 5. Make the HTTP POST request and handle the result
  print("Sending active user report to httpbin.org...\n");
  match httpRequest("POST", "https://httpbin.org/post", headers, jsonBody) {
    Ok(resp) => {
      print("Request successful!\n");
      print("Status: " ++ show(resp.status) ++ "\n");
      print("--- Response Body ---\n");
      print(resp.body ++ "\n")
    },
    Err(e) => {
      -- Use println from std/io for error messages
      println("HTTP Request failed: " ++ show(e))
    }
  }
}

-- Helper function to get the length of a list
export func length[a](xs: [a]) -> int {
  match xs {
    [] => 0,
    Cons(_, t) => 1 + length(t)
  }
}

