module benchmark/solution

import std/io (println)

type Result[a, e] = Ok(a) | Err(e)

export func parse_int(s: string) -> Result[int, string] {
  match stringToInt(s) {
    Some(n) => Ok(n),
    None => Err("Invalid integer")
  }
}

export func divide_safe(a: int, b: int) -> Result[int, string] {
  if b == 0
  then Err("Division by zero")
  else Ok(a / b)
}

export func bind[a, b, e](f: func(a) -> Result[b, e], m: Result[a, e]) -> Result[b, e] {
  match m {
    Ok(x) => f(x),
    Err(err_val) => Err(err_val)
  }
}

export func run_test_case(input_str: string, divisor: int) -> () ! {IO} {
  let parse_op = parse_int(input_str);
  let divide_op = \val. divide_safe(val, divisor);

  let final_result = bind(divide_op, parse_op);

  match final_result {
    Ok(val) => println("Result: " ++ show(val)),
    Err(msg) => println("Error: " ++ msg)
  }
}

export func main() -> () ! {IO} {
  run_test_case("10", 2);
  run_test_case("10", 0);
  run_test_case("abc", 5)
}

