type Tree = Leaf(int) | Node(Tree, int, Tree)

export func treeMax(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(l, v, r) => {
      let lmax = treeMax(l);
      let rmax = treeMax(r);
      if v >= lmax && v >= rmax
      then v
      else if lmax >= rmax
      then lmax
      else rmax
    }
  }
}

export func main() -> () ! {IO} {
  let myTree = Node(
    Node(Leaf(1), 10, Leaf(5)),
    20,
    Node(Leaf(25), 15, Leaf(22))
  );
