export func find_max(tree: Tree) -> int {
  match tree {
    Leaf(v) => v,
    Node(l, v, r) => {
      let lmax = find_max(l);
      let rmax = find_max(r);
      if v >= lmax && v >= rmax
      then v
      else if lmax >= rmax
      then lmax
      else rmax
    }
  }
}

