import std/fs (writeFile)

type Status = Pending | InProgress | Completed

type Task = {id: int, description: string, status: Status}

export func formatStatus(status: Status) -> string =
  match status {
    Pending => "Pending",
    InProgress => "In Progress",
    Completed => "Completed"
  }

test "status formatting for Completed" =
  formatStatus(Completed) == "Completed"

test "status formatting for Pending" =
  formatStatus(Pending) == "Pending"

export func updateStatus(task: Task, newStatus: Status) -> Task =
  {task | status: newStatus}

property "updateStatus preserves id and description" (id: int, desc: string) =
  let task = {id: id, description: desc, status: Pending} in
  let updated = updateStatus(task, Completed) in
  updated.id == id && updated.description == desc

-- state is a counter of processed tasks
-- Returns (newState, newListOfTasks)
export func processTasks(tasks: List[Task], state: int) -> (int, List[Task]) =
  match tasks {
    [] => (state, []),
    Cons(task, rest) => {
      let processedTask = if task.status == Completed
                          then task
                          else updateStatus(task, Completed)
      in
      let r = processTasks(rest, state + 1) in
      match r {
        (newState, processedRest) => (newState, Cons(processedTask, processedRest))
      }
    }
  }

test "processTasks updates all tasks and counts them" =
  let tasks = [{id: 1, description: "A", status: Pending}, {id: 2, description: "B", status: InProgress}] in
  let result = processTasks(tasks, 0) in
  match result {
    (count, updatedTasks) => {
      let statusesCorrect = match updatedTasks {
        Cons(t1, Cons(t2, [])) => t1.status == Completed && t2.status == Completed,
        _ => false
      } in
      count == 2 && statusesCorrect
    }
  }

export func generateReport(tasks: List[Task], count: int) -> string =
  let header = "Processing Report: " ++ show(count) ++ " tasks processed.\n" in
  letrec foldl = \f. \acc. \xs. match xs {
      [] => acc,
      Cons(x, rest) => foldl(f)(f(acc, x))(rest)
    } in
  let taskToString = \task. "- Task " ++ show(task.id) ++ ": " ++ task.description ++ " -> " ++ formatStatus(task.status) ++ "\n" in
  let body = foldl(\acc. \t. acc ++ taskToString(t))("")(tasks) in
  header ++ body

export func main() -> () ! {IO, FS} = {
  let initialTasks = [
    {id: 101, description: "Implement feature A", status: Pending},
    {id: 102, description: "Fix bug #456", status: Pending},
    {id: 103, description: "Write documentation", status: InProgress}
  ];

  print("Initial state. Processing tasks...\n");

  -- Thread state through the processing function
  let result = processTasks(initialTasks, 0);

  match result {
    (processedCount, finalTasks) => {
      print("Processing complete.\n");
      let report = generateReport(finalTasks, processedCount);
      print("-- REPORT START --\n");
      print(report);
      print("-- REPORT END --\n\n");
      print("Saving report to tasks.log...\n");
      match writeFile("tasks.log", report) {
        Ok(()) => print("Report saved successfully.\n"),
        Err(e) => print("Error saving report: " ++ show(e) ++ "\n")
      }
    }
  }
}

